edits.after:
	struct igmphdr *pig = igmp_hdr(skb);
	const int igmplen = skb_tail_pointer(skb) - skb_transport_header(skb);
	int ret;

	pig->csum = ip_compute_csum(igmp_hdr(skb), igmplen);

	rcu_read_lock();
	ret = ip_local_out(dev_net(skb_dst(skb)->dev), skb->sk, skb);
	rcu_read_unlock();
	return ret;
